import zipfile, re, copy
from lxml import etree
from diff_match_patch import diff_match_patch
W="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML_SPACE="{http://www.w3.org/XML/1998/namespace}space"
def q(t): return "{%s}%s"%(W,t)
AUTHOR="Whitfield Greer & Associates LLP"; DATE="2025-05-09T09:00:00Z"
_rid=[1000]
def rid():
    _rid[0]+=1; return str(_rid[0])
def mk_t(text, deleted=False):
    t=etree.Element(q("delText" if deleted else "t")); t.text=text; t.set(XML_SPACE,"preserve"); return t
def mk_run(text, rpr, deleted=False):
    r=etree.Element(q("r"))
    if rpr is not None: r.append(copy.deepcopy(rpr))
    r.append(mk_t(text,deleted)); return r
def wrap(kind, runs):
    e=etree.Element(q(kind)); e.set(q("id"),rid()); e.set(q("author"),AUTHOR); e.set(q("date"),DATE)
    for r in runs: e.append(r)
    return e
def ptext(p): return "".join(t.text or "" for t in p.iter(q("t")))
def cleanup(body):
    for p in body.iter(q("p")):
        ts=[t for t in p.iter(q("t"))]
        prev=""
        for i,t in enumerate(ts):
            if t.text==" " and prev.endswith(" "): t.text=""
            prev = (prev + (t.text or ""))
        # strip leading space
        for t in ts:
            if t.text:
                if t.text.startswith(" ") and ts.index(t)==0 or (t.text.startswith(" ") and "".join((x.text or "") for x in ts[:ts.index(t)])==""):
                    t.text=t.text.lstrip(" ")
                break
def char_map(p):
    chars=[]
    for r in p.findall(q("r")):
        if r.find(q("br")) is not None or r.find(q("tab")) is not None: raise Exception("br/tab in para")
        rpr=r.find(q("rPr"))
        for t in r.findall(q("t")):
            for c in (t.text or ""): chars.append((c,rpr))
    return chars
TOK=re.compile(r"\w+|\s+|[^\w\s]")
def word_diff(a,b):
    ta=TOK.findall(a); tb=TOK.findall(b); m={}; inv=[]
    def enc(toks):
        s=[]
        for tk in toks:
            if tk not in m: m[tk]=chr(0xE000+len(inv)) if len(inv)<6000 else None; inv.append(tk)
            s.append(m[tk])
        return "".join(s)
    ea,eb=enc(ta),enc(tb)
    d=diff_match_patch(); diffs=d.diff_main(ea,eb,False); d.diff_cleanupSemantic(diffs)
    out=[]
    for op,s in diffs:
        out.append((op,"".join(inv[ord(c)-0xE000] for c in s)))
    return out
def same(r1,r2):
    a=etree.tostring(r1) if r1 is not None else b""; b=etree.tostring(r2) if r2 is not None else b""; return a==b
def segs(chars):
    # group consecutive chars with same rpr
    out=[]
    for c,r in chars:
        if out and same(out[-1][1],r): out[-1][0]+=c
        else: out.append([c,r])
    return out
def replace_para(p,new):
    chars=char_map(p); old="".join(c for c,_ in chars)
    assert old!=new, "no change: "+old[:60]
    diffs=word_diff(old,new)
    for r in p.findall(q("r")): p.remove(r)
    pos=0; last_rpr=chars[0][1] if chars else None; pending_del_rpr=None
    for op,s in diffs:
        if op==0:
            for txt,r in segs(chars[pos:pos+len(s)]): p.append(mk_run(txt,r))
            last_rpr=chars[pos+len(s)-1][1]; pos+=len(s); pending_del_rpr=None
        elif op==-1:
