            if rpr is not None and pending_del_rpr is None and (rpr.find(q("b")) is not None or rpr.find(q("i")) is not None) and pos<len(chars):
                nxt=chars[pos][1]
                rpr=nxt
            p.append(wrap("ins",[mk_run(s,rpr)]))
    assert pos==len(chars)
BASE_RPR=None
def mk_rpr(fmt):
    r=etree.Element(q("rPr"))
    f=etree.SubElement(r,q("rFonts")); f.set(q("ascii"),"Times New Roman"); f.set(q("hAnsi"),"Times New Roman")
    if "b" in fmt: etree.SubElement(r,q("b"))
    if "i" in fmt: etree.SubElement(r,q("i"))
