    s=etree.SubElement(r,q("sz")); s.set(q("val"),"22")
    return r
def mark_ppr(p,kind):
    ppr=p.find(q("pPr"))
    if ppr is None: ppr=etree.Element(q("pPr")); p.insert(0,ppr)
    rpr=ppr.find(q("rPr"))
    if rpr is None: rpr=etree.SubElement(ppr,q("rPr"))
    e=etree.SubElement(rpr,q(kind)); e.set(q("id"),rid()); e.set(q("author"),AUTHOR); e.set(q("date"),DATE)
def insert_para_after(ref,segments):
    p=etree.Element(q("p"))
    ppr=ref.find(q("pPr"))
    if ppr is not None:
        ppr=copy.deepcopy(ppr)
        old=ppr.find(q("rPr"))
        if old is not None: ppr.remove(old)
        p.append(ppr)
    mark_ppr(p,"ins")
    p.append(wrap("ins",[mk_run(t,mk_rpr(f)) for t,f in segments]))
    ref.addnext(p); return p
def delete_para(p):
    chars=char_map(p)
    for r in p.findall(q("r")): p.remove(r)
    p.append(wrap("del",[mk_run(t,r,True) for t,r in segs(chars)]))
    mark_ppr(p,"del")
