    for i,pt in enumerate(parts):
        if not pt: continue
        r=p.add_run(pt); r.bold = bold or (i%2==1); r.italic=italic
        if size: r.font.size=Pt(size)
    return p
def body(text): return para(text,align="j")
def head(text): 
